    id_error: 'E' + String(nomor).padStart(4, '0'),
    waktu,
    workflow: workflow || '',
    node: node || '',
    pesan: potong(bersihkan(pesanError(error)), BATAS_PESAN),
    data_masukan: dataMasukanAman(masukan),
  };
}

